public static void Build(){Folder(Root);parts.Clear();temporary.Clear();rng=new System.Random(261028);var land=Mat("LandBaseNeutral",new Color(.48f,.49f,.47f));var paving=Mat("YardBaseNeutral",new Color(.53f,.53f,.50f));var wall=Mat("QuayBaseNeutral",new Color(.42f,.43f,.41f));var cap=Mat("QuayTopNeutral",new Color(.57f,.57f,.53f));var mats=new[]{land,paving,wall,cap};
