Box(r,"ContinuousLand",new Vector3(-1375,-4,0),new Vector3(3250,8,6000),land);int tris=Bake(r,"ContinuousLandSurface",mats);var floor=root.AddComponent<BoxCollider>();floor.center=new Vector3(-1375,-4,0);floor.size=new Vector3(3250,8,6000);
Quad(r,"IndustrialApron",-125,0,750,1200,.004f,paving);tris+=Bake(r,"IndustrialApron_BaseMaterialOnly",mats);
