var guides=new GameObject("LayoutAnchors_EmptyObjects_NoGroundPaint");guides.transform.SetParent(r,false);foreach(int x in new[]{-150,150})foreach(int z in new[]{-250,250}){var g=new GameObject("CombatCorner_"+x+"_"+z);g.transform.SetParent(guides.transform,false);g.transform.localPosition=new Vector3(x,0,z);}var ocean=new GameObject("FutureOcean_EmptyAnchor_Yminus3_X251plus");ocean.transform.SetParent(r,false);ocean.transform.localPosition=new Vector3(251,-3,0);
