static void MakeRobot(string name,Vector3 position,float yaw,Material mat){var asset=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_Anseong/Art/Robot/Source/BossUpdatedCompatible.fbx");if(!asset)throw new Exception("Scale robot missing");var g=(GameObject)PrefabUtility.InstantiatePrefab(asset);g.name=name;g.transform.rotation=Quaternion.Euler(0,yaw,0);var renderers=g.GetComponentsInChildren<Renderer>();Bounds b=renderers[0].bounds;foreach(var rr in renderers)b.Encapsulate(rr.bounds);g.transform.localScale*=65/b.size.y;b=renderers[0].bounds;foreach(var rr in renderers)b.Encapsulate(rr.bounds);g.transform.position+=position-new Vector3(b.center.x,b.min.y,b.center.z);foreach(var rr in renderers){var slots=rr.sharedMaterials;for(int i=0;i<slots.Length;i++)slots[i]=mat;rr.sharedMaterials=slots;}Bounds check=renderers[0].bounds;foreach(var rr in renderers)check.Encapsulate(rr.bounds);if(Mathf.Abs(check.size.y-65)>.2f)throw new Exception("Robot scale check failed "+check.size.y);}static void Capture(Camera c,string n){var rt=new RenderTexture(1600,1100,24);rt.antiAliasing=4;c.targetTexture=rt;c.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1600,1100,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1600,1100),0,0);t.Apply();File.WriteAllBytes("C:/Users/Admin/Documents/ChatGPT/안성제철/output/"+n+".png",t.EncodeToPNG());c.targetTexture=null;RenderTexture.active=prev;Object.DestroyImmediate(rt);Object.DestroyImmediate(t);}
